package com.sirithree.shopops.admin.benchmark.v1.dataset.stage7a;
import static org.assertj.core.api.Assertions.assertThat; import org.junit.jupiter.api.Test; import java.util.*; import java.util.stream.Collectors;
class TaskScaleupCoverageTest { @Test void scaleupAddsIndependentCoverageAcrossAllFourDomains() throws Exception { var cases=Stage7ATaskDatasetSupport.taskCases(); assertThat(cases).hasSize(189); assertThat(Stage7ATaskDatasetSupport.roots()).hasSize(116); Map<String,Long> roots=Stage7ATaskDatasetSupport.roots().entrySet().stream().collect(Collectors.groupingBy(e->e.getValue().get(0).benchmarkCase().scenario,Collectors.counting())); assertThat(roots).containsEntry("daily_review",29L).containsEntry("comment_risk",28L).containsEntry("product_optimization",30L).containsEntry("ad_anomaly",29L); }}
